// Generated by AI, edited by humans

export interface SliderStep {
    value: number
    label?: string
}

export interface SingleSliderOptions {
    container: HTMLElement
    interactionContainer?: HTMLElement
    min?: number
    max?: number
    step?: number
    initialValue?: number
    enableSnapping?: boolean
    showDots?: boolean
    minDistanceForDotsPx?: number // e.g. 30px
    onChange?: (value: number) => void
    onInput?: (value: number) => void
}

export interface RangeSliderOptions {
    container: HTMLElement
    min?: number
    max?: number
    step?: number
    initialStart?: number
    initialEnd?: number
    onChange?: (start: number, end: number) => void
    onInput?: (start: number, end: number) => void
}

/**
 * Universal Single-Handle Slider with Pointer Capture and optional rubber-band snapping.
 */
export class ElasticSlider {
    private container: HTMLElement
    private interactionArea: HTMLElement
    private thumb: HTMLElement
    private trackBg: HTMLElement
    private dotsContainer: HTMLElement | null = null

    private min: number
    private max: number
    private step: number
    private value: number
    private enableSnapping: boolean
    private showDots: boolean
    private minDistanceForDotsPx: number

    private isDragging = false
    private startX = 0
    private startVal = 0

    private currentVisualX = 0
    private targetVisualX = 0
    private animFrameId: number | null = null

    private onInputCallback?: (val: number) => void
    private onChangeCallback?: (val: number) => void

    constructor(options: SingleSliderOptions) {
        this.container = options.container
        this.interactionArea = options.interactionContainer ?? options.container
        this.min = options.min ?? 0
        this.max = options.max ?? 10
        this.step = options.step ?? 1
        this.value = options.initialValue ?? this.max
        this.enableSnapping = options.enableSnapping ?? true
        this.showDots = options.showDots ?? true
        this.minDistanceForDotsPx = options.minDistanceForDotsPx ?? 30
        this.onInputCallback = options.onInput
        this.onChangeCallback = options.onChange

        this.container.classList.add('custom-slider-container')

        // Build DOM
        this.container.innerHTML = `
            <div class="slider-track-bg"></div>
            <div class="slider-steps-layer"></div>
            <div class="slider-thumb" tabindex="0"></div>
        `

        this.trackBg = this.container.querySelector('.slider-track-bg') as HTMLElement
        this.dotsContainer = this.container.querySelector('.slider-steps-layer') as HTMLElement
        this.thumb = this.container.querySelector('.slider-thumb') as HTMLElement

        this.setupEvents()
        this.renderDots()
        this.setValue(this.value, false)
    }

    public setBounds(min: number, max: number, keepRelative = false): void {
        const prevRatio = (this.value - this.min) / (Math.max(1, this.max - this.min))
        this.min = min
        this.max = max
        if (keepRelative) {
            this.value = min + prevRatio * (max - min)
        } else {
            this.value = Math.max(min, Math.min(max, this.value))
        }
        this.renderDots()
        this.setValue(this.value, false)
    }

    public getValue(): number {
        return this.value
    }

    private stopAnimation(): void {
        if (this.animFrameId !== null) {
            cancelAnimationFrame(this.animFrameId)
            this.animFrameId = null
        }
    }

    private startSpringAnimation(): void {
        this.stopAnimation()
        const loop = () => {
            const diff = this.targetVisualX - this.currentVisualX
            if (Math.abs(diff) < 0.2) {
                this.currentVisualX = this.targetVisualX
                this.applyVisualPosition(this.currentVisualX)
                this.animFrameId = null
                return
            }

            // Spring interpolation factor (crisp but smooth)
            this.currentVisualX += diff * 0.28
            this.applyVisualPosition(this.currentVisualX)
            this.animFrameId = requestAnimationFrame(loop)
        }
        this.animFrameId = requestAnimationFrame(loop)
    }

    private applyVisualPosition(px: number): void {
        this.thumb.style.left = `${px}px`
        this.thumb.style.transform = 'translate(-50%, -50%)'
    }

    public setValue(val: number, animate = true, triggerEvents = true): void {
        val = Math.max(this.min, Math.min(this.max, val))
        this.value = val

        const span = Math.max(1, this.max - this.min)
        const rect = this.container.getBoundingClientRect()
        const trackWidth = rect.width > 0 ? rect.width : 280
        const targetX = ((val - this.min) / span) * trackWidth

        this.targetVisualX = targetX

        if (animate) {
            this.startSpringAnimation()
        } else {
            this.stopAnimation()
            this.currentVisualX = targetX
            this.applyVisualPosition(targetX)
        }

        this.updateActiveDots()

        if (triggerEvents) {
            this.onInputCallback?.(this.value)
            this.onChangeCallback?.(this.value)
        }
    }

    private renderDots(): void {
        if (!this.dotsContainer) return
        this.dotsContainer.innerHTML = ''

        const totalSteps = Math.round((this.max - this.min) / this.step)
        const rect = this.container.getBoundingClientRect()
        const trackWidth = rect.width > 0 ? rect.width : 280
        const distancePerStep = trackWidth / Math.max(1, totalSteps)

        // Only show dots and snappy if distance between positions >= minDistanceForDotsPx
        const canShow = this.showDots && totalSteps > 0 && distancePerStep >= this.minDistanceForDotsPx

        if (!canShow) {
            return
        }

        for (let i = 0; i <= totalSteps; i++) {
            const dot = document.createElement('span')
            dot.className = 'slider-step-dot'
            dot.dataset.val = String(this.min + i * this.step)
            const pct = (i / totalSteps) * 100
            dot.style.left = `${pct}%`
            this.dotsContainer.appendChild(dot)
        }

        this.updateActiveDots()
    }

    private updateActiveDots(): void {
        if (!this.dotsContainer) return
        const dots = this.dotsContainer.querySelectorAll<HTMLElement>('.slider-step-dot')
        dots.forEach((dot) => {
            const v = Number(dot.dataset.val)
            dot.classList.toggle('active', v === this.value)
        })
    }

    private setupEvents(): void {
        const onPointerDown = (e: PointerEvent, fromTrack = false) => {
            this.isDragging = true
            this.stopAnimation()
            document.body.classList.add('slider-active-dragging')
            this.thumb.setPointerCapture(e.pointerId)
            this.thumb.classList.add('dragging')

            const rect = this.container.getBoundingClientRect()
            const trackWidth = Math.max(1, rect.width)
            const span = Math.max(1, this.max - this.min)

            if (fromTrack) {
                // Point directly under cursor on track
                const mouseTrackX = Math.max(0, Math.min(trackWidth, e.clientX - rect.left))
                const rawVal = this.min + (mouseTrackX / trackWidth) * span
                const nearestStep = Math.round((rawVal - this.min) / this.step) * this.step + this.min
                this.value = nearestStep
                this.updateActiveDots()
                this.onInputCallback?.(this.value)

                this.startX = e.clientX
                this.startVal = rawVal
                this.currentVisualX = mouseTrackX
                this.targetVisualX = mouseTrackX
                this.applyVisualPosition(mouseTrackX)
            } else {
                this.startX = e.clientX
                this.startVal = this.value
                this.currentVisualX = ((this.value - this.min) / span) * trackWidth
                this.targetVisualX = this.currentVisualX
            }
        }

        const onPointerMove = (e: PointerEvent) => {
            if (!this.isDragging) return
            const rect = this.container.getBoundingClientRect()
            const trackWidth = Math.max(1, rect.width)
            const span = Math.max(1, this.max - this.min)
            const totalSteps = span / this.step
            const stepPx = trackWidth / totalSteps

            const isSnappingActive = this.enableSnapping && stepPx >= this.minDistanceForDotsPx

            // Virtual continuous target under mouse
            const deltaX = e.clientX - this.startX
            const targetPosVal = this.startVal + (deltaX / trackWidth) * span
            const clampedVal = Math.max(this.min, Math.min(this.max, targetPosVal))

            if (isSnappingActive) {
                // Find nearest step (switches exactly at the 50% midpoint)
                const nearestStep = Math.round((clampedVal - this.min) / this.step) * this.step + this.min
                if (nearestStep !== this.value) {
                    this.value = nearestStep
                    this.updateActiveDots()
                    this.onInputCallback?.(this.value)
                }

                // Snap anchor position
                const snappedX = ((this.value - this.min) / span) * trackWidth
                // Continuous mouse position on track
                const mouseX = ((clampedVal - this.min) / span) * trackWidth
                const displacementFromAnchor = mouseX - snappedX

                // 50% movement rule: thumb is at anchor + 50% of the distance to the mouse
                this.targetVisualX = snappedX + displacementFromAnchor * 0.50

                // Smoothly converge currentVisualX towards targetVisualX without jumps
                if (this.animFrameId === null) {
                    this.startSpringAnimation()
                }
            } else {
                this.value = clampedVal
                const targetX = ((clampedVal - this.min) / span) * trackWidth
                this.currentVisualX = targetX
                this.applyVisualPosition(targetX)
                this.onInputCallback?.(this.value)
            }
        }

        const onPointerUp = (e: PointerEvent) => {
            if (!this.isDragging) return
            this.isDragging = false
            document.body.classList.remove('slider-active-dragging')
            this.thumb.classList.remove('dragging')
            try {
                this.thumb.releasePointerCapture(e.pointerId)
            } catch {}

            // Snap smoothly to exact final step anchor
            const steppedVal = Math.round((this.value - this.min) / this.step) * this.step + this.min
            this.setValue(steppedVal, true, true)
        }

        this.thumb.addEventListener('pointerdown', (e) => onPointerDown(e, false))
        this.thumb.addEventListener('pointermove', onPointerMove)
        this.thumb.addEventListener('pointerup', onPointerUp)
        this.thumb.addEventListener('pointercancel', onPointerUp)

        // Click/drag on track or expanded interaction area: place thumb directly under cursor and initiate dragging
        this.interactionArea.addEventListener('pointerdown', (e) => {
            if (e.target === this.thumb) return
            onPointerDown(e, true)
        })

        // Keyboard
        this.thumb.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
                e.preventDefault()
                this.setValue(this.value + this.step, true, true)
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
                e.preventDefault()
                this.setValue(this.value - this.step, true, true)
            }
        })

        window.addEventListener('resize', () => {
            this.renderDots()
            this.setValue(this.value, false, false)
        })
    }
}

/**
 * Universal Dual-Handle Range Slider with Pointer Capture and grabbing cursor lock.
 */
export class ElasticRangeSlider {
    private container: HTMLElement
    private thumbStart: HTMLElement
    private thumbEnd: HTMLElement
    private trackBg: HTMLElement
    private highlight: HTMLElement

    private min: number
    private max: number
    private step: number
    private valStart: number
    private valEnd: number

    private activeDragThumb: 'start' | 'end' | null = null
    private startX = 0
    private startVal = 0

    private onInputCallback?: (start: number, end: number) => void
    private onChangeCallback?: (start: number, end: number) => void

    constructor(options: RangeSliderOptions) {
        this.container = options.container
        this.min = options.min ?? 0
        this.max = options.max ?? 100
        this.step = options.step ?? 1
        this.valStart = options.initialStart ?? this.min
        this.valEnd = options.initialEnd ?? this.max
        this.onInputCallback = options.onInput
        this.onChangeCallback = options.onChange

        this.container.classList.add('custom-slider-container', 'custom-range-container')

        // Build DOM
        this.container.innerHTML = `
            <div class="slider-track-bg"></div>
            <div class="slider-track-highlight"></div>
            <div class="slider-thumb range-thumb-start" data-thumb="start" tabindex="0"></div>
            <div class="slider-thumb range-thumb-end" data-thumb="end" tabindex="0"></div>
        `

        this.trackBg = this.container.querySelector('.slider-track-bg') as HTMLElement
        this.highlight = this.container.querySelector('.slider-track-highlight') as HTMLElement
        this.thumbStart = this.container.querySelector('.range-thumb-start') as HTMLElement
        this.thumbEnd = this.container.querySelector('.range-thumb-end') as HTMLElement

        this.setupEvents()
        this.render()
    }

    public setBounds(min: number, max: number, keepRelative = false): void {
        const prevSpan = Math.max(1, this.max - this.min)
        const ratioStart = (this.valStart - this.min) / prevSpan
        const ratioEnd = (this.valEnd - this.min) / prevSpan

        this.min = min
        this.max = max
        const newSpan = Math.max(1, max - min)

        if (keepRelative) {
            this.valStart = min + ratioStart * newSpan
            this.valEnd = min + ratioEnd * newSpan
        } else {
            this.valStart = min
            this.valEnd = max
        }

        this.render()
    }

    public getRange(): { start: number; end: number } {
        return {
            start: Math.min(this.valStart, this.valEnd),
            end: Math.max(this.valStart, this.valEnd)
        }
    }

    public setRange(start: number, end: number, triggerEvents = true): void {
        this.valStart = Math.max(this.min, Math.min(this.max, start))
        this.valEnd = Math.max(this.min, Math.min(this.max, end))
        this.render()

        if (triggerEvents) {
            const res = this.getRange()
            this.onInputCallback?.(res.start, res.end)
            this.onChangeCallback?.(res.start, res.end)
        }
    }

    private render(): void {
        const span = Math.max(1, this.max - this.min)
        const s = Math.min(this.valStart, this.valEnd)
        const e = Math.max(this.valStart, this.valEnd)

        const pctStart = ((s - this.min) / span) * 100
        const pctEnd = ((e - this.min) / span) * 100

        this.highlight.style.left = `${pctStart}%`
        this.highlight.style.width = `${pctEnd - pctStart}%`

        const pctThumb1 = ((this.valStart - this.min) / span) * 100
        const pctThumb2 = ((this.valEnd - this.min) / span) * 100

        this.thumbStart.style.left = `${pctThumb1}%`
        this.thumbEnd.style.left = `${pctThumb2}%`
    }

    private setupEvents(): void {
        const startDrag = (thumbEl: HTMLElement, type: 'start' | 'end', e: PointerEvent) => {
            this.activeDragThumb = type
            document.body.classList.add('slider-active-dragging')
            thumbEl.setPointerCapture(e.pointerId)
            thumbEl.classList.add('dragging')
            this.startX = e.clientX
            this.startVal = type === 'start' ? this.valStart : this.valEnd
        }

        const onPointerMove = (thumbEl: HTMLElement, type: 'start' | 'end', e: PointerEvent) => {
            if (this.activeDragThumb !== type) return
            const rect = this.container.getBoundingClientRect()
            const trackWidth = Math.max(1, rect.width)
            const span = Math.max(1, this.max - this.min)

            const deltaX = e.clientX - this.startX
            const targetVal = this.startVal + (deltaX / trackWidth) * span
            const clampedVal = Math.max(this.min, Math.min(this.max, targetVal))

            if (type === 'start') {
                this.valStart = clampedVal
            } else {
                this.valEnd = clampedVal
            }

            this.render()
            const res = this.getRange()
            this.onInputCallback?.(res.start, res.end)
        }

        const endDrag = (thumbEl: HTMLElement, type: 'start' | 'end', e: PointerEvent) => {
            if (this.activeDragThumb !== type) return
            this.activeDragThumb = null
            document.body.classList.remove('slider-active-dragging')
            thumbEl.classList.remove('dragging')
            try {
                thumbEl.releasePointerCapture(e.pointerId)
            } catch {}

            const res = this.getRange()
            this.onChangeCallback?.(res.start, res.end)
        }

        // Thumb 1
        this.thumbStart.addEventListener('pointerdown', (e) => startDrag(this.thumbStart, 'start', e))
        this.thumbStart.addEventListener('pointermove', (e) => onPointerMove(this.thumbStart, 'start', e))
        this.thumbStart.addEventListener('pointerup', (e) => endDrag(this.thumbStart, 'start', e))
        this.thumbStart.addEventListener('pointercancel', (e) => endDrag(this.thumbStart, 'start', e))

        // Thumb 2
        this.thumbEnd.addEventListener('pointerdown', (e) => startDrag(this.thumbEnd, 'end', e))
        this.thumbEnd.addEventListener('pointermove', (e) => onPointerMove(this.thumbEnd, 'end', e))
        this.thumbEnd.addEventListener('pointerup', (e) => endDrag(this.thumbEnd, 'end', e))
        this.thumbEnd.addEventListener('pointercancel', (e) => endDrag(this.thumbEnd, 'end', e))

        window.addEventListener('resize', () => {
            this.render()
        })
    }
}
